import { useState, useCallback, useRef, useEffect } from 'react';
import i18n from '~/shared/i18n/i18n';
import { BaseSelectItem } from './base-select-item';
import { ConfirmButton } from './confirm-button';
import { SelectStyle, BaseSelectListProps, LabelChangeProps, SelectOption, OnClickProps } from './types';
import { useScrollIntoView } from './use-scroll-into-view';

export const BaseSelectList = <T,>({
  options,
  selectedOption,
  valueKey,
  description,
  defaultSelectedOption,
  onLabelChange,
  selectStyle = SelectStyle.DEFAULT,
  shouldShowConfirmButton = false,
  confirmButtonLabel = i18n.t('confirm'),
  onConfirm,
  maxHeight,
}: BaseSelectListProps<T>) => {
  const [tempSelectedOption, setTempSelectedOption] = useState<SelectOption<T> | undefined>(
    selectedOption || defaultSelectedOption,
  );
  const rafRef = useRef<number>();
  const isInitialMount = useRef(true);

  useEffect(() => {
    if (isInitialMount.current && defaultSelectedOption && !tempSelectedOption) {
      isInitialMount.current = false;
      setTempSelectedOption(defaultSelectedOption);
    }
  }, [defaultSelectedOption, onLabelChange, tempSelectedOption]);

  const { refs } = useScrollIntoView({
    options,
    selectedOption,
    tempSelectedOption,
    shouldShowConfirmButton,
  });

  const handleOptionSelect = useCallback(
    ({ event, option }: LabelChangeProps<unknown> | OnClickProps<unknown>) => {
      if (option.disabled) {
        return;
      }

      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }

      rafRef.current = requestAnimationFrame(() => {
        setTempSelectedOption(option as SelectOption<T>);
      });

      onLabelChange?.({ event, option } as LabelChangeProps<T>);
    },
    [onLabelChange],
  );

  const handleRadioChange = useCallback(
    (props: LabelChangeProps<unknown>) => {
      handleOptionSelect(props);
    },
    [handleOptionSelect],
  );

  const handleClick = useCallback(
    (props: OnClickProps<unknown>) => {
      handleOptionSelect(props);
    },
    [handleOptionSelect],
  );

  const handleConfirm = (event: React.MouseEvent<HTMLButtonElement>) => {
    const finalSelectedOption = shouldShowConfirmButton ? tempSelectedOption : selectedOption;
    if (finalSelectedOption && !finalSelectedOption.disabled) {
      onConfirm?.({ event, selectedOption: finalSelectedOption });
    }
  };

  const isOptionSelected = useCallback((option: SelectOption<T>, selectedOpt?: SelectOption<T>) => {
    if (!selectedOpt || option.disabled) return false;
    return option.value === selectedOpt.value || option.label === selectedOpt.label;
  }, []);

  return (
    <>
      <div className="bottom-sheet-content">
        {description && (
          <div className="caption-info-message">
            <i className="icon-caption-info" aria-hidden="true"></i>
            <span>{description}</span>
          </div>
        )}
        <ul
          className="period-select-list"
          style={maxHeight ? { maxHeight, overflowY: 'auto' } : undefined}
        >
          {options?.map((option, index) => (
            <BaseSelectItem
              key={valueKey && option.value ? `${option.value[valueKey]}` : option.label}
              option={option}
              index={index}
              isSelected={isOptionSelected(option, tempSelectedOption)}
              selectStyle={selectStyle}
              onRadioChange={handleRadioChange}
              onClick={handleClick}
              refs={refs}
            />
          ))}
        </ul>
      </div>
      {shouldShowConfirmButton && <ConfirmButton confirmButtonLabel={confirmButtonLabel} onConfirm={handleConfirm} />}
    </>
  );
};
